BEGIN;

UPDATE public.questions q
SET explanation_data = explanation_data || jsonb_build_object('viz', v.viz)
FROM (VALUES
  ('ap-server-q1', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="20" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">MTBF（故障〜故障の平均間隔）</text><line x1="20" y1="60" x2="320" y2="60" stroke="#2a2f3f" stroke-width="1.5"/><circle cx="60" cy="60" r="4" fill="#c47070"/><circle cx="160" cy="60" r="4" fill="#c47070"/><circle cx="280" cy="60" r="4" fill="#c47070"/><text x="60" y="78" font-size="10" fill="#8892a4" text-anchor="middle" font-weight="normal">故障</text><text x="160" y="78" font-size="10" fill="#8892a4" text-anchor="middle" font-weight="normal">故障</text><text x="280" y="78" font-size="10" fill="#8892a4" text-anchor="middle" font-weight="normal">故障</text><line x1="60" y1="95" x2="160" y2="95" stroke="#60a5fa" stroke-width="2"/><text x="110" y="90" font-size="10" fill="#60a5fa" text-anchor="middle" font-weight="normal">MTBF</text><line x1="160" y1="95" x2="280" y2="95" stroke="#60a5fa" stroke-width="2"/><text x="170" y="118" font-size="11" fill="#8892a4" text-anchor="middle" font-weight="normal">この間隔の平均がMTBF</text></svg>'),
  ('ap-server-q4', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="18" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">直列接続：どちらかが止まれば全体が止まる</text><rect x="40" y="45" width="90" height="40" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="85" y="69" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーA</text><line x1="130" y1="65" x2="170" y2="65" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="210" y="45" width="90" height="40" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="255" y="69" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーB</text><text x="170" y="110" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">稼働率 = Aの稼働率 × Bの稼働率（掛けるほど下がる）</text></svg>'),
  ('ap-server-q5', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="18" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">並列接続：両方止まらない限り生きている</text><rect x="90" y="35" width="90" height="32" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="135" y="56" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーA</text><rect x="90" y="78" width="90" height="32" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="135" y="99" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーB</text><line x1="50" y1="55" x2="90" y2="51" stroke="#8892a4" stroke-width="1.5"/><line x1="50" y1="55" x2="90" y2="94" stroke="#8892a4" stroke-width="1.5"/><line x1="180" y1="51" x2="220" y2="55" stroke="#8892a4" stroke-width="1.5"/><line x1="180" y1="94" x2="220" y2="55" stroke="#8892a4" stroke-width="1.5"/><text x="170" y="122" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">稼働率 = 1 − （両方が同時に止まる確率）</text></svg>'),
  ('ap-server-q6', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="85" y="18" font-size="12" fill="#60a5fa" text-anchor="middle" font-weight="normal">直列</text><text x="255" y="18" font-size="12" fill="#60a5fa" text-anchor="middle" font-weight="normal">並列</text><rect x="40" y="30" width="90" height="26" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="85" y="47" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">A → B</text><text x="85" y="75" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">掛け算で</text><text x="85" y="90" font-size="10.5" fill="#c47070" text-anchor="middle" font-weight="normal">稼働率が下がる</text><rect x="210" y="30" width="90" height="26" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="255" y="47" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">A ∥ B</text><text x="255" y="75" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">片方生きてれば</text><text x="255" y="90" font-size="10.5" fill="#6ab08d" text-anchor="middle" font-weight="normal">稼働率が上がる</text><text x="170" y="120" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">同じ2台でも、つなぎ方で結果は正反対</text></svg>'),
  ('ap-server-q7', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="18" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">直列3台：掛け算がもう一段増える</text><rect x="20" y="45" width="80" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="60" y="66" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">0.9</text><line x1="102" y1="62" x2="122" y2="62" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="130" y="45" width="80" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="66" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">0.9</text><line x1="212" y1="62" x2="232" y2="62" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="240" y="45" width="80" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="280" y="66" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">0.9</text><text x="170" y="105" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">0.9 × 0.9 × 0.9 と、つなぐたび掛け算が増える</text><text x="170" y="122" font-size="10.5" fill="#c47070" text-anchor="middle" font-weight="normal">→ 台数が増えるほど全体の稼働率は下がる</text></svg>'),
  ('ap-server-q8', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="18" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">RAID0：分散して書く（冗長性なし）</text><rect x="40" y="35" width="70" height="70" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="75" y="58" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">Disk1</text><text x="75" y="74" font-size="9.5" fill="#8892a4" text-anchor="middle" font-weight="normal">データA</text><rect x="135" y="35" width="70" height="70" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="58" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">Disk2</text><text x="170" y="74" font-size="9.5" fill="#8892a4" text-anchor="middle" font-weight="normal">データB</text><rect x="230" y="35" width="70" height="70" rx="4" fill="none" stroke="#c47070" stroke-width="1.5"/><text x="265" y="58" font-size="10" fill="#c47070" text-anchor="middle" font-weight="normal">1台故障</text><text x="265" y="74" font-size="9.5" fill="#c47070" text-anchor="middle" font-weight="normal">＝全滅</text><text x="170" y="122" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">速いが、コピーが無いので1台の故障で全部消える</text></svg>'),
  ('ap-server-q11', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="18" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">RAID1（ミラーリング）500GB×2台</text><rect x="60" y="40" width="100" height="55" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="110" y="62" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">Disk1</text><text x="110" y="80" font-size="10" fill="#8892a4" text-anchor="middle" font-weight="normal">500GB</text><text x="170" y="68" font-size="14" fill="#8892a4" text-anchor="middle" font-weight="normal">＝</text><rect x="210" y="40" width="100" height="55" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="260" y="62" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">Disk2</text><text x="260" y="80" font-size="10" fill="#6ab08d" text-anchor="middle" font-weight="normal">500GBの複製</text><text x="170" y="118" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">同じ内容の複製なので、使える容量は1台分だけ</text></svg>'),
  ('ap-server-q12', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="18" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">RAID5：250GB×4台の内訳</text><rect x="20" y="40" width="70" height="50" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><rect x="100" y="40" width="70" height="50" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><rect x="180" y="40" width="70" height="50" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><rect x="260" y="40" width="70" height="50" rx="4" fill="none" stroke="#c9a04a" stroke-width="1.5"/><text x="55" y="62" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">250GB</text><text x="135" y="62" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">250GB</text><text x="215" y="62" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">250GB</text><text x="295" y="62" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">250GB</text><text x="55" y="78" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="normal">データ</text><text x="135" y="78" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="normal">データ</text><text x="215" y="78" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="normal">データ</text><text x="295" y="78" font-size="9" fill="#c9a04a" text-anchor="middle" font-weight="normal">パリティ相当</text><text x="170" y="118" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">4台のうち1台分をパリティに回す → 実効容量は3台分</text></svg>'),
  ('ap-server-q14', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="18" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">RAID0のリスク：保険が無い</text><rect x="60" y="40" width="90" height="45" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="105" y="66" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">Disk1 正常</text><rect x="190" y="40" width="90" height="45" rx="4" fill="none" stroke="#c47070" stroke-width="1.5"/><text x="235" y="66" font-size="10.5" fill="#c47070" text-anchor="middle" font-weight="normal">Disk2 故障</text><line x1="60" y1="100" x2="280" y2="100" stroke="#c47070" stroke-width="2"/><text x="170" y="118" font-size="10.5" fill="#c47070" text-anchor="middle" font-weight="normal">1台でも壊れると、全データが読み出せなくなる</text></svg>'),
  ('ap-server-q15', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="12" fill="#60a5fa" text-anchor="middle" font-weight="normal">ロードバランサ</text><rect x="140" y="25" width="60" height="24" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="41" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">LB</text><line x1="160" y1="49" x2="80" y2="78" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><line x1="170" y1="49" x2="170" y2="78" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><line x1="180" y1="49" x2="260" y2="78" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="50" y="80" width="60" height="34" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="80" y="101" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーA</text><rect x="140" y="80" width="60" height="34" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="170" y="101" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーB</text><rect x="230" y="80" width="60" height="34" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="260" y="101" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーC</text><text x="170" y="130" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">来た処理を複数のサーバーに振り分ける</text></svg>'),
  ('ap-server-q17', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="18" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">Active-Standby：待機系は普段休んでいる</text><rect x="50" y="40" width="100" height="50" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="100" y="62" font-size="12" fill="#6ab08d" text-anchor="middle" font-weight="normal">Active</text><text x="100" y="78" font-size="10" fill="#8892a4" text-anchor="middle" font-weight="normal">処理中</text><rect x="190" y="40" width="100" height="50" rx="4" fill="none" stroke="#c9a04a" stroke-width="1.5"/><text x="240" y="62" font-size="12" fill="#c9a04a" text-anchor="middle" font-weight="normal">Standby</text><text x="240" y="78" font-size="9.5" fill="#8892a4" text-anchor="middle" font-weight="normal">電源ONで待機</text><text x="170" y="118" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">Activeが壊れたらStandbyに切り替える</text></svg>'),
  ('ap-server-q18', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="20" y="45" width="80" height="40" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="60" y="69" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーA</text><line x1="105" y1="60" x2="135" y2="60" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="140" y="45" width="60" height="40" rx="4" fill="none" stroke="#c47070" stroke-width="1.5"/><text x="170" y="63" font-size="10" fill="#c47070" text-anchor="middle" font-weight="normal">共通</text><text x="170" y="76" font-size="9.5" fill="#c47070" text-anchor="middle" font-weight="normal">の1点</text><line x1="205" y1="60" x2="235" y2="60" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="240" y="45" width="80" height="40" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="280" y="69" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーB</text><text x="170" y="100" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">ここが壊れると、他が無事でも全体が止まる</text><text x="170" y="120" font-size="11" fill="#c47070" text-anchor="middle" font-weight="normal">＝単一障害点（SPOF）</text></svg>'),
  ('ap-server-q21', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">ラウンドロビン：順番に均等に回す</text><rect x="140" y="25" width="60" height="22" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="40" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">LB</text><text x="80" y="62" font-size="10" fill="#60a5fa" text-anchor="middle" font-weight="normal">①</text><rect x="50" y="68" width="60" height="30" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="80" y="88" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">A</text><text x="170" y="62" font-size="10" fill="#60a5fa" text-anchor="middle" font-weight="normal">②</text><rect x="140" y="68" width="60" height="30" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="170" y="88" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">B</text><text x="260" y="62" font-size="10" fill="#60a5fa" text-anchor="middle" font-weight="normal">③</text><rect x="230" y="68" width="60" height="30" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="260" y="88" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">C</text><text x="170" y="122" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">次のリクエストはまたAへ… と巡回する</text></svg>'),
  ('ap-server-q22', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="30" y="45" width="70" height="40" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="65" y="69" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">送信者</text><line x1="105" y1="65" x2="155" y2="65" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><text x="130" y="55" font-size="10" fill="#60a5fa" text-anchor="middle" font-weight="normal">SMTP</text><rect x="160" y="45" width="70" height="40" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="195" y="69" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">メール</text><line x1="235" y1="65" x2="285" y2="65" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="240" y="45" width="70" height="40" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="275" y="69" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">受信者</text><text x="170" y="110" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">メールを「送る」ときに使われるプロトコル</text></svg>'),
  ('ap-server-q23', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">POP：手元に落として、サーバーから消す</text><rect x="50" y="35" width="80" height="40" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="90" y="59" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバー</text><line x1="140" y1="55" x2="200" y2="55" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><text x="170" y="45" font-size="9.5" fill="#60a5fa" text-anchor="middle" font-weight="normal">ダウンロード</text><rect x="210" y="35" width="80" height="40" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="250" y="59" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">手元の端末</text><text x="90" y="100" font-size="10" fill="#c47070" text-anchor="middle" font-weight="normal">（空に）</text><text x="170" y="122" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">他の端末からは、もう見えなくなる</text></svg>'),
  ('ap-server-q24', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">IMAP：サーバー上に残したまま見に行く</text><rect x="120" y="25" width="100" height="36" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="47" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバー（保管）</text><line x1="140" y1="61" x2="90" y2="88" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><line x1="200" y1="61" x2="250" y2="88" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="50" y="90" width="70" height="28" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="85" y="108" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">PC</text><rect x="220" y="90" width="70" height="28" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="255" y="108" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">スマホ</text><text x="170" y="132" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">どちらから見ても同じ状態が見える</text></svg>'),
  ('ap-server-q25', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="40" y="45" width="90" height="40" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="85" y="69" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">新しい端末</text><text x="170" y="52" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="normal">IPアドレス</text><line x1="130" y1="60" x2="200" y2="60" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><text x="170" y="92" font-size="9" fill="#60a5fa" text-anchor="middle" font-weight="normal">192.168.1.5 どうぞ</text><line x1="200" y1="84" x2="130" y2="84" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="210" y="45" width="90" height="40" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="255" y="69" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">DHCPサーバー</text><text x="170" y="118" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">設定を自動で割り当ててもらう</text></svg>'),
  ('ap-server-q26', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="140" y="25" width="60" height="30" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="44" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">正確な時計</text><line x1="140" y1="55" x2="90" y2="80" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><line x1="200" y1="55" x2="250" y2="80" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="50" y="82" width="70" height="30" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="85" y="100" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">PC</text><text x="85" y="112" font-size="8.5" fill="#60a5fa" text-anchor="middle" font-weight="normal">時計合わせ</text><rect x="220" y="82" width="70" height="30" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="255" y="100" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバー</text><text x="255" y="112" font-size="8.5" fill="#60a5fa" text-anchor="middle" font-weight="normal">時計合わせ</text><text x="170" y="130" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">みんなの時計を1つの正確な時計に合わせる</text></svg>'),
  ('ap-server-q27', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">HTTPステータスコードの帯</text><rect x="20" y="32" width="70" height="26" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="55" y="49" font-size="9.5" fill="#8892a4" text-anchor="middle" font-weight="normal">1xx 情報</text><rect x="95" y="32" width="70" height="26" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="130" y="49" font-size="9.5" fill="#6ab08d" text-anchor="middle" font-weight="normal">2xx 成功</text><rect x="170" y="32" width="70" height="26" rx="4" fill="none" stroke="#c9a04a" stroke-width="1.5"/><text x="205" y="49" font-size="9.5" fill="#c9a04a" text-anchor="middle" font-weight="normal">3xx 転送</text><rect x="245" y="32" width="70" height="26" rx="4" fill="none" stroke="#c47070" stroke-width="1.5"/><text x="280" y="49" font-size="9.5" fill="#c47070" text-anchor="middle" font-weight="normal">4xx 依頼側</text><rect x="95" y="65" width="150" height="26" rx="4" fill="none" stroke="#c47070" stroke-width="1.5"/><text x="170" y="82" font-size="9.5" fill="#c47070" text-anchor="middle" font-weight="normal">5xx サーバー側の失敗</text><text x="170" y="118" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">先頭の数字だけで、大まかな意味が分かる</text></svg>'),
  ('ap-server-q30', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="30" y="45" width="90" height="34" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="75" y="66" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">元のデータ</text><line x1="125" y1="62" x2="165" y2="62" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><text x="145" y="50" font-size="9.5" fill="#60a5fa" text-anchor="middle" font-weight="normal">ハッシュ関数</text><rect x="175" y="45" width="130" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="240" y="66" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">a1b2c3d4… 固定長</text><text x="170" y="100" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">1文字変えるだけで、値は大きく変わる</text><text x="170" y="118" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">→ 改ざんの検知に使える</text></svg>'),
  ('ap-server-q31', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="20" y="50" width="80" height="34" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="60" y="71" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">Webサイト</text><text x="170" y="40" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="normal">この鍵は本物？</text><rect x="140" y="50" width="60" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="71" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">認証局</text><text x="225" y="40" font-size="9" fill="#60a5fa" text-anchor="middle" font-weight="normal">証明する</text><rect x="240" y="50" width="80" height="34" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="280" y="71" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">利用者</text><line x1="100" y1="67" x2="140" y2="67" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><line x1="200" y1="67" x2="240" y2="67" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><text x="170" y="108" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">信頼できる第三者が「本物」だと保証する</text></svg>'),
  ('ap-server-q32', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="12" fill="#60a5fa" text-anchor="middle" font-weight="normal">デジタル署名</text><rect x="30" y="35" width="80" height="30" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="70" y="54" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">送信者</text><text x="70" y="78" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="normal">自分の秘密鍵で</text><text x="70" y="90" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="normal">署名を付ける</text><line x1="115" y1="50" x2="210" y2="50" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="220" y="35" width="90" height="30" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="265" y="54" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">受信者</text><text x="265" y="78" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="normal">送信者の公開鍵で</text><text x="265" y="90" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="normal">確認する</text><text x="170" y="118" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">本人性となりすまし防止を確認できる</text></svg>'),
  ('ap-server-q34', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">正規化する前：同じ情報を何度も書く</text><rect x="30" y="30" width="280" height="24" rx="4" fill="none" stroke="#c47070" stroke-width="1.5"/><text x="170" y="46" font-size="9.5" fill="#c47070" text-anchor="middle" font-weight="normal">注文1: りんご 100円</text><rect x="30" y="58" width="280" height="24" rx="4" fill="none" stroke="#c47070" stroke-width="1.5"/><text x="170" y="74" font-size="9.5" fill="#c47070" text-anchor="middle" font-weight="normal">注文2: りんご 100円 ← また同じ</text><text x="170" y="100" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">商品テーブルを分ければ、単価は1か所だけ</text><text x="170" y="118" font-size="10.5" fill="#6ab08d" text-anchor="middle" font-weight="normal">→ 変更漏れ・矛盾を防げる</text></svg>'),
  ('ap-server-q35', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">第1正規形：1マスに1つの値</text><rect x="40" y="32" width="120" height="30" rx="4" fill="none" stroke="#c47070" stroke-width="1.5"/><text x="100" y="51" font-size="9.5" fill="#c47070" text-anchor="middle" font-weight="normal">趣味: 読書, 旅行</text><text x="170" y="55" font-size="16" fill="#8892a4" text-anchor="middle" font-weight="normal">→</text><rect x="200" y="30" width="60" height="16" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="230" y="42" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="normal">読書</text><rect x="200" y="48" width="60" height="16" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="230" y="60" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="normal">旅行</text><text x="170" y="100" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">1つのマスに複数の値を詰め込まない</text><text x="170" y="118" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">→ 行を分けて1マス1値にする</text></svg>'),
  ('ap-server-q37', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">トランザクション：全部やる、か、全部やめる</text><rect x="40" y="32" width="110" height="30" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="95" y="51" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">口座A −1000円</text><rect x="190" y="32" width="110" height="30" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="245" y="51" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">口座B +1000円</text><text x="170" y="80" font-size="10.5" fill="#c47070" text-anchor="middle" font-weight="normal">どちらか片方だけ成功、は許さない</text><text x="170" y="100" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">失敗したら両方とも無かったことにする</text></svg>'),
  ('ap-server-q38', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="12" fill="#60a5fa" text-anchor="middle" font-weight="normal">ACID特性</text><rect x="30" y="30" width="70" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="65" y="50" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">原子性</text><text x="65" y="62" font-size="8.5" fill="#8892a4" text-anchor="middle" font-weight="normal">全部か無か</text><rect x="110" y="30" width="70" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="145" y="50" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">一貫性</text><text x="145" y="62" font-size="8.5" fill="#8892a4" text-anchor="middle" font-weight="normal">ルール維持</text><rect x="190" y="30" width="70" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="225" y="50" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">独立性</text><text x="225" y="62" font-size="8.5" fill="#8892a4" text-anchor="middle" font-weight="normal">干渉しない</text><rect x="270" y="30" width="60" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="300" y="50" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">永続性</text><text x="300" y="62" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">消えない</text><text x="170" y="100" font-size="10" fill="#8892a4" text-anchor="middle" font-weight="normal">4つ揃って初めて安心して使えるデータベース</text></svg>'),
  ('ap-server-q39', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="70" y="40" width="90" height="40" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="115" y="62" font-size="12" fill="#6ab08d" text-anchor="middle" font-weight="normal">コミット</text><text x="115" y="78" font-size="9.5" fill="#8892a4" text-anchor="middle" font-weight="normal">確定させる</text><rect x="190" y="40" width="90" height="40" rx="4" fill="none" stroke="#c47070" stroke-width="1.5"/><text x="235" y="62" font-size="11" fill="#c47070" text-anchor="middle" font-weight="normal">ロールバック</text><text x="235" y="78" font-size="9.5" fill="#8892a4" text-anchor="middle" font-weight="normal">元に戻す</text><text x="170" y="108" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">確定 か 取り消し、どちらかで終わる</text></svg>'),
  ('ap-server-q40', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="60" y="20" font-size="11" fill="#60a5fa" text-anchor="start" font-weight="normal">SELECT</text><text x="60" y="34" font-size="9" fill="#8892a4" text-anchor="start" font-weight="normal">何を出すか</text><text x="150" y="20" font-size="11" fill="#60a5fa" text-anchor="start" font-weight="normal">FROM</text><text x="150" y="34" font-size="9" fill="#8892a4" text-anchor="start" font-weight="normal">どこから</text><text x="230" y="20" font-size="11" fill="#60a5fa" text-anchor="start" font-weight="normal">WHERE</text><text x="230" y="34" font-size="9" fill="#8892a4" text-anchor="start" font-weight="normal">どんな条件で</text><rect x="30" y="55" width="280" height="30" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="74" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">name FROM users WHERE age>=20</text><text x="170" y="105" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">「usersのうち20歳以上のname」を取り出す</text></svg>'),
  ('ap-server-q41', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="60" y="40" width="90" height="40" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="105" y="62" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">1分間に</text><text x="105" y="78" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">300件</text><text x="170" y="65" font-size="14" fill="#8892a4" text-anchor="middle" font-weight="normal">÷60</text><rect x="190" y="40" width="90" height="40" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="235" y="62" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">1秒あたり</text><text x="235" y="78" font-size="12" fill="#6ab08d" text-anchor="middle" font-weight="normal">？件</text><text x="170" y="108" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">「1分」を「1秒」の単位にそろえるだけ</text></svg>'),
  ('ap-server-q42', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><line x1="30" y1="60" x2="310" y2="60" stroke="#2a2f3f" stroke-width="1.5"/><text x="30" y="40" font-size="10" fill="#8892a4" text-anchor="start" font-weight="normal">依頼</text><text x="150" y="40" font-size="10" fill="#60a5fa" text-anchor="start" font-weight="normal">最初の反応</text><line x1="30" y1="60" x2="150" y2="60" stroke="#60a5fa" stroke-width="3"/><text x="90" y="78" font-size="10" fill="#8892a4" text-anchor="middle" font-weight="normal">ここまでがレスポンスタイム</text><text x="280" y="40" font-size="10" fill="#8892a4" text-anchor="start" font-weight="normal">完了</text><text x="170" y="115" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">「最初の反応」までの時間、という点に注意</text></svg>'),
  ('ap-server-q43', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">1時間のうち45分ふさがっていた</text><rect x="40" y="35" width="260" height="34" rx="4" fill="none" stroke="#2a2f3f" stroke-width="1.5"/><rect x="40" y="35" width="195" height="34" rx="4" fill="#c47070" stroke="none" stroke-width="1.5"/><text x="137" y="57" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">処理中 45分</text><rect x="235" y="35" width="65" height="34" rx="4" fill="none" stroke="#2a2f3f" stroke-width="1.5"/><text x="267" y="57" font-size="9.5" fill="#8892a4" text-anchor="middle" font-weight="normal">空き</text><text x="170" y="100" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">ふさがっていた時間 ÷ 全体の時間 ＝ 利用率</text></svg>'),
  ('ap-server-q44', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">利用率が上がるほど、待ち時間は急上昇</text><line x1="30" y1="110" x2="310" y2="110" stroke="#2a2f3f" stroke-width="1.5"/><line x1="30" y1="20" x2="30" y2="110" stroke="#2a2f3f" stroke-width="1.5"/><text x="20" y="118" font-size="9" fill="#8892a4" text-anchor="end" font-weight="normal">0%</text><text x="305" y="118" font-size="9" fill="#8892a4" text-anchor="end" font-weight="normal">100%</text><text x="15" y="60" font-size="9" fill="#8892a4" text-anchor="start" font-weight="normal">待</text><path d="M30,105 Q200,100 260,60 Q290,35 300,20" fill="none" stroke="#60a5fa" stroke-width="2.5"/><text x="170" y="133" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">満杯（100%）に近づくほど、行列が伸びていく</text></svg>'),
  ('ap-server-q47', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">レスポンスタイムの内訳</text><rect x="30" y="35" width="90" height="30" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="75" y="54" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">通信の時間</text><rect x="125" y="35" width="90" height="30" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="170" y="54" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">処理の時間</text><rect x="220" y="35" width="90" height="30" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="265" y="54" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">通信の時間</text><text x="170" y="90" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">行き＋サーバー内の処理＋帰り、の合計</text></svg>'),
  ('ap-server-q48', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="40" y="40" width="100" height="50" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="90" y="62" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">その時点の</text><text x="90" y="78" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">全データ</text><line x1="150" y1="65" x2="195" y2="65" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="200" y="40" width="100" height="50" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="250" y="62" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">バックアップ</text><text x="250" y="78" font-size="9.5" fill="#8892a4" text-anchor="middle" font-weight="normal">（丸ごと複製）</text><text x="170" y="115" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">全部を毎回まるごとコピーする</text></svg>'),
  ('ap-server-q49', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">増分バックアップ：前回からの差分だけ</text><rect x="20" y="40" width="70" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="55" y="61" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">フル</text><line x1="95" y1="57" x2="130" y2="57" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="135" y="40" width="65" height="34" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="167" y="61" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">月曜分</text><line x1="205" y1="57" x2="235" y2="57" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="240" y="40" width="65" height="34" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="272" y="61" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">火曜分</text><text x="170" y="100" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">毎回「直前」からの変更分だけを保存</text></svg>'),
  ('ap-server-q50', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="14" font-size="10.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">差分バックアップ：毎回フルからの差分</text><rect x="140" y="25" width="60" height="24" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="41" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">フル</text><line x1="150" y1="52" x2="100" y2="78" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><line x1="190" y1="52" x2="240" y2="78" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="60" y="80" width="80" height="28" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="100" y="98" font-size="9" fill="#e8eaf0" text-anchor="middle" font-weight="normal">月曜分の差分</text><rect x="200" y="80" width="80" height="28" rx="4" fill="none" stroke="#6ab08d" stroke-width="1.5"/><text x="240" y="98" font-size="9" fill="#e8eaf0" text-anchor="middle" font-weight="normal">火曜分の差分</text><text x="170" y="128" font-size="10" fill="#8892a4" text-anchor="middle" font-weight="normal">毎回「フルとの差」なので、後になるほど大きい</text></svg>'),
  ('ap-server-q52', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">RTO：どれだけ早く復旧させたいか</text><line x1="30" y1="60" x2="310" y2="60" stroke="#2a2f3f" stroke-width="1.5"/><text x="30" y="40" font-size="10" fill="#c47070" text-anchor="start" font-weight="normal">障害発生</text><line x1="30" y1="60" x2="150" y2="60" stroke="#c47070" stroke-width="3"/><text x="90" y="80" font-size="10" fill="#c47070" text-anchor="middle" font-weight="normal">RTO（この幅）</text><text x="150" y="40" font-size="10" fill="#6ab08d" text-anchor="start" font-weight="normal">復旧完了</text><text x="170" y="112" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">「発生から復旧まで」の目標時間</text></svg>'),
  ('ap-server-q53', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><text x="170" y="16" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">RPO：どの時点まで戻ってよいか</text><line x1="30" y1="60" x2="310" y2="60" stroke="#2a2f3f" stroke-width="1.5"/><text x="30" y="40" font-size="9.5" fill="#60a5fa" text-anchor="start" font-weight="normal">最後のバックアップ</text><line x1="30" y1="60" x2="150" y2="60" stroke="#60a5fa" stroke-width="3"/><text x="90" y="80" font-size="9.5" fill="#60a5fa" text-anchor="middle" font-weight="normal">RPO（この幅=失ってよい分）</text><text x="150" y="40" font-size="10" fill="#c47070" text-anchor="start" font-weight="normal">障害発生</text><text x="170" y="112" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">「どこまでのデータなら失っても許せるか」</text></svg>'),
  ('ap-server-q55', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="120" y="40" width="100" height="40" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="64" font-size="11" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバー</text><line x1="220" y1="60" x2="260" y2="60" stroke="#8892a4" stroke-width="2"/><rect x="260" y="45" width="50" height="30" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="285" y="64" font-size="9" fill="#e8eaf0" text-anchor="middle" font-weight="normal">ディスク</text><text x="170" y="105" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">サーバーに直結、そのサーバーからしか使えない</text></svg>'),
  ('ap-server-q56', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="140" y="30" width="60" height="30" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="170" y="49" font-size="12" fill="#e8eaf0" text-anchor="middle" font-weight="normal">NAS</text><line x1="140" y1="55" x2="90" y2="80" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><line x1="200" y1="55" x2="250" y2="80" stroke="#8892a4" stroke-width="1.5" marker-end="url(#arrow)"/><rect x="50" y="82" width="70" height="28" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="85" y="100" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">PC1</text><rect x="220" y="82" width="70" height="28" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="255" y="100" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">PC2</text><text x="170" y="122" font-size="10.5" fill="#8892a4" text-anchor="middle" font-weight="normal">ネットワーク越し、ファイル単位で共有</text></svg>'),
  ('ap-server-q57', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#8892a4"/></marker></defs><rect x="30" y="40" width="80" height="34" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="70" y="61" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">サーバーA</text><rect x="130" y="40" width="80" height="34" rx="4" fill="none" stroke="#8892a4" stroke-width="1.5"/><text x="170" y="61" font-size="10" fill="#60a5fa" text-anchor="middle" font-weight="normal">専用網</text><rect x="230" y="40" width="80" height="34" rx="4" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="270" y="61" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="normal">ストレージ</text><line x1="110" y1="57" x2="130" y2="57" stroke="#8892a4" stroke-width="1.5"/><line x1="210" y1="57" x2="230" y2="57" stroke="#8892a4" stroke-width="1.5"/><text x="170" y="100" font-size="10" fill="#8892a4" text-anchor="middle" font-weight="normal">高速な専用ネットワークでブロック単位のやり取り</text></svg>'),
